/* @autogenerated */
package net.civeira.phylax.features.oauth.authentication.application;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.time.Instant;
import java.util.Date;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;

import com.auth0.jwt.JWT;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.access.oauthclient.domain.AllowedLoginRedirects;
import net.civeira.phylax.features.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.features.access.oauthclient.domain.OauthClientSubjectTypeOptions;
import net.civeira.phylax.features.access.oauthclient.domain.gateway.OauthClientFilter;
import net.civeira.phylax.features.access.oauthclient.domain.gateway.OauthClientQueryRepositoryGateway;
import net.civeira.phylax.features.access.tenant.domain.Tenant;
import net.civeira.phylax.features.access.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.features.access.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.features.oauth.tokensecurity.application.SubjectResolver;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenSigner;

/**
 * Dispatches OIDC Back-Channel Logout notifications (server-to-server) to all registered Relying
 * Parties that have a {@code backchannel_logout_uri} configured.
 *
 * <p>
 * Per OIDC Back-Channel Logout spec, delivery is best-effort: a failure to notify one RP MUST NOT
 * prevent the user's session from being terminated at the IdP.
 * </p>
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class BackChannelLogoutDispatcher {

  private static final Duration HTTP_TIMEOUT = Duration.ofSeconds(5);

  private final OauthClientQueryRepositoryGateway clients;
  private final TenantQueryRepositoryGateway tenants;
  private final TokenSigner signer;
  private final SubjectResolver subjects;

  private final HttpClient http = HttpClient.newBuilder().connectTimeout(HTTP_TIMEOUT).build();

  /**
   * Sends a {@code logout_token} JWT to every RP of the tenant (its own clients and the global
   * ones) that has a {@code backchannel_logout_uri}.
   *
   * @param tenant tenant identifier used to sign tokens
   * @param issuer token {@code iss} claim
   * @param userSub subject being logged out ({@code sub} claim)
   * @param sessionId session being terminated ({@code sid} claim)
   */
  public void dispatch(String tenant, String issuer, String userSub, String sessionId) {
    dispatch(tenant, issuer, userSub, sessionId, Set.of());
  }

  public void dispatch(String tenant, String issuer, String userSub, String sessionId,
      Set<String> participants) {
    if (userSub == null || userSub.isBlank() || sessionId == null || sessionId.isBlank()) {
      return;
    }

    for (OauthClient client : recipients(tenant)) {
      if (!participants.contains(client.getCode()))
        continue;
      client.getBackchannelLogoutUri().filter(uri -> !uri.isBlank())
          .ifPresent(uri -> sendLogoutToken(tenant, issuer, subjectFor(client, userSub), sessionId,
              client.getCode(), uri));
    }
  }

  /**
   * Clients with a back-channel logout URI that the tenant sees: its own and the global ones, never
   * another tenant's (task 0.5).
   *
   * @param tenant tenant name
   * @return the clients to notify
   */
  /**
   * The {@code sub} the client knows: pairwise when it registered it (task 4.4). Without a pairwise
   * subject the token is sent with none of the user's identifiers, only the {@code sid}.
   */
  private String subjectFor(OauthClient client, String userSub) {
    try {
      return subjects.subject(OauthClientSubjectTypeOptions.PAIRWISE == client.getSubjectType(),
          client.getSectorIdentifierUri().orElse(null),
          client.getAllowedLoginRedirects().stream().map(AllowedLoginRedirects::getUrl).toList(),
          userSub);
    } catch (IllegalStateException ex) {
      log.warn("No pairwise subject for client {}: {}", client.getCode(), ex.getMessage());
      return null;
    }
  }

  List<OauthClient> recipients(String tenant) {
    Optional<String> tenantUid =
        tenants.find(TenantFilter.builder().name(tenant).build()).map(Tenant::getUid);
    if (tenantUid.isEmpty()) {
      return List.of();
    }
    // The generated withBackchannelLogoutUrl filter currently selects IS NULL; filter non-empty
    // registered URIs here so no RP is silently lost from a logout notification.
    return clients.list(OauthClientFilter.builder().build()).stream()
        .filter(c -> c.getTenantUid().map(tenantUid.get()::equals).orElse(true))
        .filter(c -> c.getBackchannelLogoutUri().filter(uri -> !uri.isBlank()).isPresent())
        .toList();
  }

  private void sendLogoutToken(String tenant, String issuer, String userSub, String sessionId,
      String clientId, String uri) {
    try {
      String logoutToken = buildLogoutToken(tenant, issuer, userSub, sessionId, clientId);
      String body = "logout_token=" + logoutToken;

      HttpRequest request = HttpRequest.newBuilder().uri(URI.create(uri)).timeout(HTTP_TIMEOUT)
          .header("Content-Type", "application/x-www-form-urlencoded")
          .POST(HttpRequest.BodyPublishers.ofString(body)).build();

      http.sendAsync(request, HttpResponse.BodyHandlers.discarding()).exceptionally(ex -> {
        log.warn("Back-channel logout notification failed for client={} uri={}: {}", clientId, uri,
            ex.getMessage());
        return null;
      });
    } catch (Exception ex) {
      // Best-effort per spec — log but never propagate
      log.warn("Back-channel logout dispatch error for client={} uri={}: {}", clientId, uri,
          ex.getMessage());
    }
  }

  private String buildLogoutToken(String tenant, String issuer, String userSub, String sessionId,
      String clientId) {
    Instant expiry = Instant.now().plus(Duration.ofMinutes(2));
    com.auth0.jwt.JWTCreator.Builder token =
        JWT.create().withHeader(java.util.Map.of("typ", "logout+jwt")).withIssuer(issuer)
            .withIssuedAt(new Date()).withJWTId(UUID.randomUUID().toString()).withAudience(clientId)
            .withClaim("sid", sessionId).withClaim("events", java.util.Map
                .of("http://schemas.openid.net/event/backchannel-logout", java.util.Map.of()));
    if (userSub != null) {
      token = token.withSubject(userSub);
    }
    return signer.sign(tenant, token, expiry);
  }

}
